INSERT INTO `brands` VALUES (1,'Virasat Silk Weaves','Master weavers specializing in pure Varanasi Katan silk, royal Paithani, and timeless heritage handlooms passed down through generations.','/storage/brands/000000000000001.png','Certified pure silk weaves with authentic tested zari motifs.','/storage/brands/000000000000002.png','Handcrafted by national award-winning master artisans.',NULL,NULL,1,'2026-09-09 10:13:15','2026-09-09 10:47:31'),(2,'Kanjivaram Heritage','Renowned temple silk brand crafting original Kanchipuram mulberry silk sarees with heavy Korvai borders and pure zari artistry.','/storage/brands/000000000000001.png','Silk Mark certified bridal and festive heirloom weaves.',NULL,NULL,NULL,NULL,1,'2026-09-09 10:13:15','2026-09-09 10:47:31'),(3,'Chanderi Elegance','Celebrated for feather-light Chanderi silks, Maheshwari cotton-silks, and gossamer weaves enriched with delicate Meenakari bootis.','/storage/brands/000000000000002.png','Artisanal looms from the historical heartland of Madhya Pradesh.',NULL,NULL,NULL,NULL,1,'2026-09-09 10:13:15','2026-09-09 10:47:31'),(4,'Marwar Bandhej','Custodians of royal Rajasthani and Gujarati tie-dye traditions, specializing in Rai Bandhani, Gharchola, and Gota Patti festive sarees.','/storage/brands/000000000000001.png','Authentic hand-knotted tie-dye with intricate hand embroidery.',NULL,NULL,NULL,NULL,1,'2026-09-09 10:13:16','2026-09-09 10:47:31'),(5,'Sutradhar Handlooms','Ethical handloom collective dedicated to pure Tussar, organic linen, pen Kalamkari, and Sambalpuri Ikat traditions across India.','/storage/brands/000000000000002.png','Sustainably sourced natural fibers and organic vegetable dyes.',NULL,NULL,NULL,NULL,1,'2026-09-09 10:13:16','2026-09-09 10:47:31');
/*!40000 ALTER TABLE `brands` ENABLE KEYS */;
UNLOCK TABLES;

