INSERT INTO `categories` VALUES (1,'Silk Sarees','Luxurious pure silk sarees representing India’s grandest royal weaving traditions, from Varanasi to Kanchipuram.','/storage/categories/000000000000001.png','/storage/categories/000000000000002.png','',NULL,1,'2026-09-09 10:13:16','2026-09-09 12:20:19'),(2,'Regional & Handloom Sarees','Authentic regional weaves handcrafted by generational artisans across historical weaving clusters of India.','/storage/categories/000000000000003.png','/storage/categories/000000000000004.png','',NULL,1,'2026-09-09 10:13:16','2026-09-09 12:21:18'),(3,'Occasion & Designer Sarees','Contemporary festive and designer sarees featuring delicate embroidery, organza sheen, and glamorous party wear silhouettes.','/storage/categories/000000000000005.png','/storage/categories/000000000000006.png','',NULL,1,'2026-09-09 10:13:16','2026-09-09 12:21:55'),(4,'Banarasi Sarees','Opulent gold and silver brocade zari handlooms from the holy city of Varanasi.','/storage/categories/000000000000006.png','/storage/categories/000000000000001.png','',1,1,'2026-09-09 10:13:16','2026-09-09 12:22:40'),(5,'Kanjivaram Sarees','Heavy pure mulberry silk sarees with contrasting Korvai temple borders and mythological motifs.','/storage/categories/000000000000007.png','/storage/categories/000000000000008.png','',1,1,'2026-09-09 10:13:16','2026-09-09 12:23:15'),(6,'Tussar & Raw Silk Sarees','Richly textured indigenous wild silk sarees with natural golden sheen and earthy elegance.','/storage/categories/000000000000009.png','/storage/categories/000000000000010.png','',1,1,'2026-09-09 10:13:16','2026-09-09 12:23:41'),(7,'Paithani Sarees','Regal Maharashtrian tapestry handlooms with kaleidoscope peacock pallus and oblique square borders.','/storage/categories/000000000000011.png','/storage/categories/000000000000012.png','',1,1,'2026-09-09 10:13:16','2026-09-09 12:25:17'),(8,'Sambalpuri Ikat Sarees','Traditional Odisha double ikat bandha silk sarees with symbolic conch, floral, and wheel motifs.','/storage/categories/000000000000013.png','/storage/categories/000000000000014.png','',1,1,'2026-09-09 10:13:16','2026-09-09 12:25:51'),(9,'Chanderi Sarees','Gossamer-light silk-cotton weaves adorned with delicate Meenakari zari bootis from Madhya Pradesh.','/storage/categories/000000000000009.png','/storage/categories/000000000000003.png','',2,1,'2026-09-09 10:13:16','2026-09-09 12:26:28'),(10,'Bandhani & Bandhej Sarees','Vibrant hand-knotted tie-dye sarees with exquisite Gota Patti and mirror embellishments.','/storage/categories/000000000000010.png','/storage/categories/000000000000004.png','',2,1,'2026-09-09 10:13:16','2026-09-09 12:26:36'),(11,'Kalamkari Handblock Sarees','Handpainted Srikalahasti and Machilipatnam block printed sarees crafted with organic vegetable dyes.','/storage/categories/000000000000011.png','/storage/categories/000000000000005.png','',2,1,'2026-09-09 10:13:16','2026-09-09 12:26:43'),(12,'Linen Handloom Sarees','Pure 100-count organic flax linen sarees offering breathable luxury and refined modern draping.','/storage/categories/000000000000012.png','/storage/categories/000000000000007.png','',2,1,'2026-09-09 10:13:17','2026-09-09 12:26:08'),(13,'Maheshwari Sarees','Historical Ahilyabai Holkar inspired cotton-silk weaves featuring reversible Bugdi borders.','/storage/categories/000000000000013.png','/storage/categories/000000000000001.png','',2,1,'2026-09-09 10:13:17','2026-09-09 12:26:14'),(14,'Kasavu Kerala Sarees','Auspicious unbleached fine handloom cotton sarees with pure golden kasavu zari borders.','/storage/categories/000000000000014.png','/storage/categories/000000000000002.png','',2,1,'2026-09-09 10:13:17','2026-09-09 12:26:21'),(15,'Organza Sarees','Ethereal translucent silk organza sarees embellished with pastel resham floral embroidery.','/storage/categories/000000000000006.png','/storage/categories/000000000000007.png','',3,1,'2026-09-09 10:13:17','2026-09-09 12:27:40'),(16,'Georgette Party Sarees','Flowy premium georgette sarees with sparkling micro-sequin work and contemporary glamour.','/storage/categories/000000000000008.png','/storage/categories/000000000000009.png','',3,1,'2026-09-09 10:13:17','2026-09-09 12:27:49'),(17,'Chikankari Sarees','Delicate hand-embroidered Lucknowi Chikankari sarees accented with sparkling silver Mukaish badla work.','/storage/categories/000000000000010.png','/storage/categories/000000000000011.png','',3,1,'2026-09-09 10:13:17','2026-09-09 12:27:59'),(18,'Bhagalpuri Sarees','Artisanal Bhagalpuri Matka raw silk sarees with textured slub weaves and brushed antique zari.','/storage/categories/000000000000014.png','/storage/categories/000000000000001.png','',3,1,'2026-09-09 10:13:17','2026-09-09 12:28:10');
/*!40000 ALTER TABLE `categories` ENABLE KEYS */;
