INSERT INTO `products` VALUES (17,'Virasat Silk Weaves | Pure Banarasi Katan Silk Handloom Zari Saree','<p><strong>Pure Banarasi Katan Silk Handloom Zari Saree</strong><span><span>&nbsp;</span>is an exquisite embodiment of Varanasi\'s centuries-old handloom heritage. Handcrafted by master artisans with pure Mulberry Katan silk, this masterpiece features an intricate Kadwa floral jaal woven with royal gold and silver tested zari. The majestic borders and opulent pallu radiate royal grandeur, making it an irreplaceable treasure for bridal trousseaus, wedding receptions, and grand festivities. Comes with a matching unstitched pure silk blouse piece.</span></p>','ITM-BNS-001',4,1,1,'\"[\\\"Originating from Ahilyabai Holkar\'s royal looms of Maheshwar, MP\\\",\\\"Reversible traditional Bugdi border inspired by Narmada fort carvings\\\",\\\"Crisp yet lustrous silk warp and fine cotton weft structure\\\",\\\"Signature 5-striped Maheshwari pallu with delicate golden accents\\\",\\\"Includes running matching silk-cotton blouse piece\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"50% Silk, 50% Mercerized Cotton\\\"},{\\\"key\\\":\\\"Weave Type \\\",\\\"value\\\":\\\"Maheshwari Handloom\\\"},{\\\"key\\\":\\\"Length \\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.8 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion \\\",\\\"value\\\":\\\" Pooja, Corporate Festive & Family Functions\\\"},{\\\"key\\\":\\\"Care Instructions \\\",\\\"value\\\":\\\" Dry Clean Preferred\\\"}]\"','/storage/products/000000000000095.png','\"[\\\"/storage/products/000000000000095.png\\\",\\\"/storage/products/000000000000096.png\\\",\\\"/storage/products/000000000000097.png\\\",\\\"/storage/products/000000000000098.png\\\",\\\"/storage/products/000000000000099.png\\\",\\\"/storage/products/000000000000100.png\\\",\\\"/storage/products/000000000000101.png\\\",\\\"/storage/products/000000000000102.png\\\",\\\"/storage/products/000000000000103.png\\\"]\"',1,'50072010',2.50,2.50,5.00,'2026-09-09 10:47:33','2026-09-09 12:51:46'),(18,'Kanjivaram Heritage | Traditional Korvai Border Pure Mulberry Silk Saree','<p><strong>Traditional Korvai Border Pure Mulberry Silk Saree</strong><span><span>&nbsp;</span>is handwoven in the temple town of Kanchipuram using heavy 3-ply twisted mulberry silk yarn. Designed with the revered Korvai technique that seamlessly connects contrasting temple-inspired borders with an opulent body, this saree is adorned with intricate Mayil (peacock) and Yali motifs woven in lustrous gold zari. A quintessential bridal drape that stays luminous for generations.</span></p>','ITM-KNJ-002',5,2,1,'\"[\\\"Original 3-ply twisted pure mulberry silk with Silk Mark certification\\\",\\\"Traditional Korvai interlocking technique with contrasting temple borders\\\",\\\"Heavy gold zari pallu featuring sacred Mayil and Yali motifs\\\",\\\"Substantial weight and lustrous drape synonymous with South Indian heritage\\\",\\\"Includes contrast unstitched brocade blouse piece\\\"]\"','\"[{\\\"key\\\":\\\"Fabric \\\",\\\"value\\\":\\\" Pure Mulberry Silk & Tested Gold Zari\\\"},{\\\"key\\\":\\\"Weave Type \\\",\\\"value\\\":\\\" Traditional Korvai Handloom\\\"},{\\\"key\\\":\\\"Length \\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.8 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion \\\",\\\"value\\\":\\\"South Indian Weddings, Temple Events & Grand Festivities\\\"},{\\\"key\\\":\\\"Care Instructions \\\",\\\"value\\\":\\\" Dry Clean Only / Store in Muslin Cloth\\\"}]\"','/storage/products/000000000000104.png','\"[\\\"/storage/products/000000000000104.png\\\",\\\"/storage/products/000000000000105.png\\\",\\\"/storage/products/000000000000106.png\\\",\\\"/storage/products/000000000000107.png\\\",\\\"/storage/products/000000000000108.png\\\",\\\"/storage/products/000000000000109.png\\\",\\\"/storage/products/000000000000110.png\\\",\\\"/storage/products/000000000000111.png\\\"]\"',1,'50072010',2.50,2.50,5.00,'2026-09-09 10:47:33','2026-09-09 12:53:16'),(19,'Chanderi Elegance | Handcrafted Chanderi Silk Cotton Saree with Meenakari Booti','<p><strong>Handcrafted Chanderi Silk Cotton Saree</strong><span><span>&nbsp;</span>combines the feather-light softness of fine cotton with the shimmering luster of pure silk. Woven on traditional pit looms in Chanderi, Madhya Pradesh, it features exquisite hand-embellished Meenakari floral bootis, a delicate golden zari border, and an airy sheer texture that drapes gracefully across warm climates and evening galas.</span></p>','ITM-CHD-003',9,3,1,'\"[\\\"Ultra-lightweight and sheer Chanderi silk-cotton handloom weave\\\",\\\"Delicate handwoven Meenakari floral bootis across the body\\\",\\\"Soft golden zari border with elegant drape and natural sheen\\\",\\\"Breathable all-weather fabric offering timeless sophistication\\\",\\\"Includes running matching Chanderi blouse piece\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"Premium Faux Georgette\\\"},{\\\"key\\\":\\\"Work Type\\\",\\\"value\\\":\\\"Micro Sequins & Lurex Thread Embroidery\\\"},{\\\"key\\\":\\\"Border\\\",\\\"value\\\":\\\"Rich Velvet Piped Border\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Parties, Weddings & Evening Events\\\"},{\\\"key\\\":\\\"Blouse\\\",\\\"value\\\":\\\"Heavy Sequin Embroidered Mono Banglori Blouse Fabric\\\"}]\"','/storage/products/000000000000112.png','\"[\\\"/storage/products/000000000000112.png\\\",\\\"/storage/products/000000000000113.png\\\",\\\"/storage/products/000000000000114.png\\\",\\\"/storage/products/000000000000115.png\\\",\\\"/storage/products/000000000000116.png\\\",\\\"/storage/products/000000000000117.png\\\",\\\"/storage/products/000000000000118.png\\\"]\"',0,'52085110',2.50,2.50,5.00,'2026-09-09 10:47:33','2026-09-09 12:43:36'),(20,'Virasat Silk Weaves | Royal Yeola Paithani Pure Silk Saree with Peacock Pallu','<p><strong>Royal Yeola Paithani Pure Silk Saree</strong><span><span>&nbsp;</span>is the quintessential crown jewel of Maharashtra\'s regal sartorial culture. Handcrafted in Yeola with rich filature silk yarns and shimmering metallic zari, it boasts the iconic kaleidoscope Mor-Bangadi (peacock in bangle) pallu motif and an oblique Narali border. Revered for its dual-sided reversible weave, it is a magnificent bridal statement.</span></p>','ITM-PTH-004',7,1,1,'\"[\\\"Authentic Yeola Paithani handwoven with fine silk and gold zari\\\",\\\"Signature kaleidoscope Mor-Bangadi (peacock in bangle) pallu design\\\",\\\"Oblique square design border (Narali border) with rich texture\\\",\\\"Double-sided reversible weave indicating genuine artisan craftsmanship\\\",\\\"Includes running pure silk blouse piece\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"Pure Silk & Tested Zari\\\"},{\\\"key\\\":\\\"Weave Type\\\",\\\"value\\\":\\\"Tapestry Handloom Weave\\\"},{\\\"key\\\":\\\"Length\\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.8 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Maharashtrian Weddings, Diwali & Grand Festivities\\\"},{\\\"key\\\":\\\"Care Instructions\\\",\\\"value\\\":\\\"Dry Clean Only, Air Periodically\\\"}]\"','/storage/products/000000000000119.png','\"[\\\"/storage/products/000000000000119.png\\\",\\\"/storage/products/000000000000120.png\\\",\\\"/storage/products/000000000000121.png\\\",\\\"/storage/products/000000000000122.png\\\",\\\"/storage/products/000000000000123.png\\\",\\\"/storage/products/000000000000124.png\\\"]\"',0,'50072010',2.50,2.50,5.00,'2026-09-09 10:47:33','2026-09-09 12:44:06'),(21,'Marwar Bandhej | Traditional Rai Bandhani Silk Georgette Saree with Gota Patti','<p><strong>Traditional Rai Bandhani Silk Georgette Saree</strong><span><span>&nbsp;</span>is handcrafted using thousands of micro-knotted tie-dye bindings (Rai Bandhej) crafted by master artisans of Jamnagar. Set against a fluid, crinkled pure viscose georgette base, the saree is framed by an artisanal handcrafted Gota Patti, dori, and pearl scallop border that glistens under festive chandeliers.</span></p>','ITM-BDH-005',10,4,1,'\"[\\\"Micro-dot Rai Bandhej tied by hand by artisans of Jamnagar and Kutch\\\",\\\"Heavy handcrafted Gota Patti and dori border along the entire perimeter\\\",\\\"Pure flowy viscose georgette base with crinkled authentic texture\\\",\\\"Vibrant ombre dual-tone colorway reflecting Rajasthani royal charm\\\",\\\"Includes embroidered designer blouse piece\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"Pure Viscose Georgette\\\"},{\\\"key\\\":\\\"Technique\\\",\\\"value\\\":\\\"Hand Tie & Dye (Bandhani) with Gota Work\\\"},{\\\"key\\\":\\\"Length\\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.8 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Karwa Chauth, Sangeet, Mehendi & Festivals\\\"},{\\\"key\\\":\\\"Care Instructions\\\",\\\"value\\\":\\\"Dry Clean Only (Do not iron directly on Gota)\\\"}]\"','/storage/products/000000000000125.png','\"[\\\"/storage/products/000000000000125.png\\\",\\\"/storage/products/000000000000126.png\\\",\\\"/storage/products/000000000000127.png\\\",\\\"/storage/products/000000000000128.png\\\",\\\"/storage/products/000000000000129.png\\\",\\\"/storage/products/000000000000130.png\\\",\\\"/storage/products/000000000000131.png\\\",\\\"/storage/products/000000000000132.png\\\"]\"',0,'54075210',2.50,2.50,5.00,'2026-09-09 10:47:33','2026-09-09 12:44:45'),(22,'Sutradhar Handlooms | Pure Sambalpuri Bandha Double Ikat Silk Saree','<p><strong>Pure Sambalpuri Bandha Double Ikat Silk Saree</strong><span><span>&nbsp;</span>is an exemplary artistic achievement of Odisha weavers. Utilizing the complex double ikat resist-dye technique, both warp and weft threads are precision-dyed prior to weaving to compose spiritual motifs including the Shankha (conch shell), Chakra, and sacred lotus. Soft, lustrous, and rich with cultural reverence.</span></p>','ITM-SMB-006',8,5,1,'\"[\\\"Authentic Odisha Double Ikat (Bandhakala) tie-and-dye weaving\\\",\\\"Motifs representing sacred conch (Shankha), wheel (Chakra), and flora\\\",\\\"Pure handspun mulberry silk with matte, regal finish\\\",\\\"Contrast traditional rudraksha border with geometric woven pallu\\\",\\\"Includes running Ikat silk blouse fabric\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"Pure Handloom Silk\\\"},{\\\"key\\\":\\\"Weave Type\\\",\\\"value\\\":\\\"Double Ikat Handloom (Bandha)\\\"},{\\\"key\\\":\\\"Length\\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.8 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Cultural Celebrations, Temple Events & Formal Evenings\\\"},{\\\"key\\\":\\\"Care Instructions\\\",\\\"value\\\":\\\"Dry Clean Only\\\"}]\"','/storage/products/000000000000001.png','\"[\\\"/storage/products/000000000000001.png\\\",\\\"/storage/products/000000000000002.png\\\",\\\"/storage/products/000000000000003.png\\\",\\\"/storage/products/000000000000004.png\\\",\\\"/storage/products/000000000000005.png\\\",\\\"/storage/products/000000000000006.png\\\",\\\"/storage/products/000000000000007.png\\\",\\\"/storage/products/000000000000008.png\\\",\\\"/storage/products/000000000000009.png\\\",\\\"/storage/products/000000000000010.png\\\"]\"',0,'50072010',2.50,2.50,5.00,'2026-09-09 10:47:34','2026-09-09 12:34:01'),(23,'Sutradhar Handlooms | Handpainted Srikalahasti Pen Kalamkari Tussar Silk Saree','<p><strong>Handpainted Srikalahasti Pen Kalamkari Tussar Silk Saree</strong><span><span>&nbsp;</span>is a wearable handpainted painting created over 3 weeks by Srikalahasti master artisans. Using a bamboo pen (kalam) and organic natural dyes extracted from jaggery, alum, and madder root, it portrays poetic mythological narratives and Tree of Life flora over handspun golden Tussar silk.</span></p>','ITM-KLM-007',11,5,1,'\"[\\\"Authentic Srikalahasti freehand pen Kalamkari using natural vegetable dyes\\\",\\\"Mythological Tree of Life and dancing peacock narrative across pallu\\\",\\\"Pure wild Tussar (Kosa) silk base with rich organic texture\\\",\\\"Each saree is a unique one-of-a-kind wearable art masterpiece\\\",\\\"Includes unstitched handpainted Tussar silk blouse piece\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"100% Pure Desi Tussar Silk\\\"},{\\\"key\\\":\\\"Art Form\\\",\\\"value\\\":\\\"Authentic Pen Kalamkari (Vegetable Dyes)\\\"},{\\\"key\\\":\\\"Length\\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.85 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Art Exhibitions, Festive Gatherings & Elite Convocations\\\"},{\\\"key\\\":\\\"Care Instructions\\\",\\\"value\\\":\\\"Dry Clean Only, Preserve in Shade\\\"}]\"','/storage/products/000000000000012.png','\"[\\\"/storage/products/000000000000011.png\\\",\\\"/storage/products/000000000000012.png\\\",\\\"/storage/products/000000000000013.png\\\",\\\"/storage/products/000000000000014.png\\\",\\\"/storage/products/000000000000015.png\\\",\\\"/storage/products/000000000000016.png\\\",\\\"/storage/products/000000000000017.png\\\",\\\"/storage/products/000000000000018.png\\\",\\\"/storage/products/000000000000019.png\\\"]\"',1,'50072010',2.50,2.50,5.00,'2026-09-09 10:47:34','2026-09-09 12:34:27'),(24,'Sutradhar Handlooms | 100 Count Organic Handloom Linen Saree with Silver Zari','<p><strong>100 Count Organic Handloom Linen Saree</strong><span><span>&nbsp;</span>redefines effortless understated luxury. Spun from certified organic flax fibers and woven on heritage handlooms, this saree pairs an ultra-breathable, softened natural drape with a minimalist matte silver zari selvedge and pinstriped pallu. Ideal for sophisticated boardroom meetings and tranquil day festivities.</span></p>','ITM-LNN-008',12,5,1,'\"[]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"100% Pure Organic Linen (100 Count)\\\"},{\\\"key\\\":\\\"Weave Type\\\",\\\"value\\\":\\\"Handloom Plain Weave with Zari Selvedge\\\"},{\\\"key\\\":\\\"Length\\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.8 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Office Wear, Summer Brunches & Casual Outings\\\"},{\\\"key\\\":\\\"Care Instructions\\\",\\\"value\\\":\\\"Gentle Hand Wash in Cold Water or Dry Clean\\\"}]\"','/storage/products/000000000000023.png','\"[\\\"/storage/products/000000000000020.png\\\",\\\"/storage/products/000000000000023.png\\\",\\\"/storage/products/000000000000024.png\\\",\\\"/storage/products/000000000000025.png\\\",\\\"/storage/products/000000000000026.png\\\",\\\"/storage/products/000000000000027.png\\\",\\\"/storage/products/000000000000028.png\\\",\\\"/storage/products/000000000000029.png\\\",\\\"/storage/products/000000000000030.png\\\",\\\"/storage/products/000000000000031.png\\\",\\\"/storage/products/000000000000032.png\\\"]\"',0,'53091900',2.50,2.50,5.00,'2026-09-09 10:47:34','2026-09-09 12:35:44'),(25,'Chanderi Elegance | Heritage Maheshwari Silk Cotton Saree with Bugdi Border','<p><strong>Heritage Maheshwari Silk Cotton Saree</strong><span><span>&nbsp;</span>is an iconic royal textile inspired by Queen Ahilyabai Holkar\'s 18th-century court. Crafted with a lustrous silk warp and fine combed cotton weft, it showcases the famous reversible Bugdi border inspired by the architectural carvings of the Maheshwar Fort overlooking the holy Narmada River.</span></p>','ITM-MSH-009',13,3,1,'\"[\\\"Originating from Ahilyabai Holkar\'s royal looms of Maheshwar, MP\\\",\\\"Reversible traditional Bugdi border inspired by Narmada fort carvings\\\",\\\"Crisp yet lustrous silk warp and fine cotton weft structure\\\",\\\"Signature 5-striped Maheshwari pallu with delicate golden accents\\\",\\\"Includes running matching silk-cotton blouse piece\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"50% Silk, 50% Mercerized Cotton\\\"},{\\\"key\\\":\\\"Weave Type\\\",\\\"value\\\":\\\"Maheshwari Handloom\\\"},{\\\"key\\\":\\\"Length\\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.8 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Pooja, Corporate Festive & Family Functions\\\"},{\\\"key\\\":\\\"Care Instructions\\\",\\\"value\\\":\\\"Dry Clean Preferred\\\"}]\"','/storage/products/000000000000033.png','\"[\\\"/storage/products/000000000000033.png\\\",\\\"/storage/products/000000000000034.png\\\",\\\"/storage/products/000000000000035.png\\\",\\\"/storage/products/000000000000036.png\\\",\\\"/storage/products/000000000000037.png\\\",\\\"/storage/products/000000000000038.png\\\",\\\"/storage/products/000000000000039.png\\\",\\\"/storage/products/000000000000040.png\\\"]\"',0,'52085110',2.50,2.50,5.00,'2026-09-09 10:47:34','2026-09-09 12:36:13'),(26,'Kanjivaram Heritage | Traditional Kerala Kasavu Handloom Cotton Saree with Golden Kara','<p><strong>Traditional Kerala Kasavu Handloom Cotton Saree</strong><span><span>&nbsp;</span>is the timeless symbol of God\'s Own Country. Woven in Balaramapuram with unbleached organic cotton yarns, it features a gleaming 3-inch pure golden Kasavu zari kara (border) and temple motif pallu. Pure, auspicious, and lightweight, it captures pristine southern traditional charm.</span></p>','ITM-KSV-010',14,2,1,'\"[\\\"Handcrafted in Balaramapuram with unbleached organic fine cotton\\\",\\\"Rich 3-inch pure gold kasavu (zari) border and temple motif pallu\\\",\\\"Iconic off-white and golden cream palette representing purity and auspiciousness\\\",\\\"Crisp natural drape perfect for festive traditions and auspicious ceremonies\\\",\\\"Includes contrast unstitched kasavu border blouse piece\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"100% Fine Organic Cotton & Zari\\\"},{\\\"key\\\":\\\"Weave Type\\\",\\\"value\\\":\\\"Traditional Kerala Handloom\\\"},{\\\"key\\\":\\\"Length\\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.8 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Onam, Vishu, Temple Weddings & Auspicious Days\\\"},{\\\"key\\\":\\\"Care Instructions\\\",\\\"value\\\":\\\"Hand Wash with Mild Detergent / Dry Clean\\\"}]\"','/storage/products/000000000000042.png','\"[\\\"/storage/products/000000000000041.png\\\",\\\"/storage/products/000000000000042.png\\\",\\\"/storage/products/000000000000043.png\\\",\\\"/storage/products/000000000000044.png\\\",\\\"/storage/products/000000000000045.png\\\",\\\"/storage/products/000000000000046.png\\\",\\\"/storage/products/000000000000047.png\\\",\\\"/storage/products/000000000000048.png\\\",\\\"/storage/products/000000000000049.png\\\"]\"',0,'52085110',2.50,2.50,5.00,'2026-09-09 10:47:34','2026-09-09 12:36:41'),(27,'Marwar Bandhej | Pastel Floral Embroidered Pure Organza Silk Saree','<p><strong>Pastel Floral Embroidered Pure Organza Silk Saree</strong><span><span>&nbsp;</span>is an ethereal masterpiece tailored for the modern romantic. Featuring sheer silk organza in refreshing pastel shades, it is elevated by delicate resham thread floral motifs, hand-applied pearl accents, and a scalloped cutwork border that flows with effortless modern poise.</span></p>','ITM-ORG-011',15,4,1,'\"[\\\"Ultra-lightweight and sheer Chanderi silk-cotton handloom weave  \\\",\\\"Delicate handwoven Meenakari floral bootis across the body\\\",\\\"Soft golden zari border with elegant drape and natural sheen\\\",\\\"Breathable all-weather fabric offering timeless sophistication \\\",\\\" Includes running matching Chanderi blouse piece\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"Pure Silk Organza\\\"},{\\\"key\\\":\\\"Embroidery\\\",\\\"value\\\":\\\"Hand & Machine Resham Floral Work with Cutwork\\\"},{\\\"key\\\":\\\"Length\\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.85 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Cocktails, Engagement, Day Weddings & Reception\\\"},{\\\"key\\\":\\\"Care Instructions\\\",\\\"value\\\":\\\"Dry Clean Only, Do Not Squeeze\\\"}]\"','/storage/products/000000000000050.png','\"[\\\"/storage/products/000000000000050.png\\\",\\\"/storage/products/000000000000051.png\\\",\\\"/storage/products/000000000000052.png\\\",\\\"/storage/products/000000000000053.png\\\",\\\"/storage/products/000000000000054.png\\\",\\\"/storage/products/000000000000055.png\\\",\\\"/storage/products/000000000000056.png\\\",\\\"/storage/products/000000000000057.png\\\",\\\"/storage/products/000000000000058.png\\\"]\"',0,'50072010',2.50,2.50,5.00,'2026-09-09 10:47:34','2026-09-09 12:48:30'),(28,'Marwar Bandhej | Glamorous 9mm Sequin & Threadwork Party Georgette Saree','<p><strong>Glamorous Sequin Party Georgette Saree</strong><span><span>&nbsp;</span>is designed to captivate night celebrations and cocktail receptions. Cut from ultra-supple 60g viscose georgette, the body is blanketed in shimmering micro-sequins and metallic lurex threads that cascade into a plush velvet hem, providing a silhouette of show-stopping elegance.</span></p>','ITM-GGT-012',16,4,1,'\"[\\\"Premium 60-gram faux georgette base with effortless fluid fall\\\",\\\"All-over tone-on-tone micro sequins and lurex thread embroidery\\\",\\\"Rich velvet piped border offering structured elegance and weight\\\",\\\"Body-hugging silhouette designed for party glamour and evening lights\\\",\\\"Includes heavy sequin embroidered mono banglori blouse fabric\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"Heavy Viscose Georgette\\\"},{\\\"key\\\":\\\"Work\\\",\\\"value\\\":\\\"Tonal Sequin Embroidery & Velvet Piping\\\"},{\\\"key\\\":\\\"Length\\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.8 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Sangeet, Cocktail Parties & Farewell Evenings\\\"},{\\\"key\\\":\\\"Care Instructions\\\",\\\"value\\\":\\\"Dry Clean Only\\\"}]\"','/storage/products/000000000000059.png','\"[\\\"/storage/products/000000000000059.png\\\",\\\"/storage/products/000000000000060.png\\\",\\\"/storage/products/000000000000061.png\\\",\\\"/storage/products/000000000000062.png\\\",\\\"/storage/products/000000000000063.png\\\",\\\"/storage/products/000000000000064.png\\\",\\\"/storage/products/000000000000065.png\\\",\\\"/storage/products/000000000000066.png\\\",\\\"/storage/products/000000000000067.png\\\",\\\"/storage/products/000000000000068.png\\\"]\"',0,'54075210',2.50,2.50,5.00,'2026-09-09 10:47:34','2026-09-09 12:38:24'),(29,'Virasat Silk Weaves | Handcrafted Lucknowi Chikankari & Mukaish Work Georgette Saree','<p><strong>Handcrafted Lucknowi Chikankari & Mukaish Saree</strong><span><span>&nbsp;</span>is an aristocratic creation representing the finest Awadhi craftsmanship. Painstakingly hand-embroidered using traditional Bakhiya, Phanda, and Keel Kangan stitches over 45 dedicated artisan days, it is embellished with hand-hammered real silver Mukaish dots that glisten subtly across the fluid georgette fabric.</span></p>','ITM-CHK-013',17,1,1,'\"[\\\"Authentic hand-embroidered Lucknowi Chikankari with Bakhiya and Phanda stitches\\\",\\\"Detailed with hand-embossed silver Mukaish (badla) dots across the entire body\\\",\\\"Pure flowy viscous georgette base dyed in royal pastel tones\\\",\\\"Intricate paisleys (Kalka) jaal and heavy floral border crafted over 45 days\\\",\\\"Includes matching hand-embroidered blouse piece\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"Pure Viscose Georgette\\\"},{\\\"key\\\":\\\"Art Form\\\",\\\"value\\\":\\\"Authentic Hand Chikankari with Real Mukaish Work\\\"},{\\\"key\\\":\\\"Length\\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.85 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Weddings, Royal Soirees & Eid Celebrations\\\"},{\\\"key\\\":\\\"Care Instructions\\\",\\\"value\\\":\\\"Dry Clean Only\\\"}]\"','/storage/products/000000000000069.png','\"[\\\"/storage/products/000000000000069.png\\\",\\\"/storage/products/000000000000070.png\\\",\\\"/storage/products/000000000000071.png\\\",\\\"/storage/products/000000000000072.png\\\",\\\"/storage/products/000000000000073.png\\\",\\\"/storage/products/000000000000074.png\\\",\\\"/storage/products/000000000000075.png\\\",\\\"/storage/products/000000000000076.png\\\"]\"',0,'54075210',2.50,2.50,5.00,'2026-09-09 10:47:34','2026-09-09 12:38:59'),(30,'Sutradhar Handlooms | Pure Desi Tussar Silk Saree with Bagru Handblock Print','<p><strong>Pure Desi Tussar Silk Saree with Bagru Handblock Print</strong><span><span>&nbsp;</span>celebrates India\'s rich tribal silk harvesting and indigenous block-printing traditions. Harvested from wild silkworms, the textured golden Tussar fabric features hand-pressed Bagru vegetable dye motifs and a delicate woven antique zari temple border. Distinctive, breathable, and deeply authentic.</span></p>','ITM-TSR-014',6,5,1,'\"[\\\"100% Wild Tussar Silk characterized by golden sheen and rich textured slubs\\\",\\\"Artisanal wooden block prints utilizing eco-friendly natural vegetable pigments\\\",\\\"Zari woven temple border framing rustic heritage motifs\\\",\\\"Silk Mark certified authentic indigenous wild silk\\\",\\\"Includes contrasting unstitched handblock printed Tussar blouse fabric\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"100% Pure Desi Tussar Silk\\\"},{\\\"key\\\":\\\"Technique\\\",\\\"value\\\":\\\"Handblock Print & Handloom Zari Border\\\"},{\\\"key\\\":\\\"Length\\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.8 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Ethnic Gatherings, Corporate Events & Festive Occasions\\\"},{\\\"key\\\":\\\"Care Instructions\\\",\\\"value\\\":\\\"Dry Clean Recommended\\\"}]\"','/storage/products/000000000000077.png','\"[\\\"/storage/products/000000000000077.png\\\",\\\"/storage/products/000000000000078.png\\\",\\\"/storage/products/000000000000079.png\\\",\\\"/storage/products/000000000000080.png\\\",\\\"/storage/products/000000000000081.png\\\",\\\"/storage/products/000000000000082.png\\\",\\\"/storage/products/000000000000083.png\\\",\\\"/storage/products/000000000000084.png\\\",\\\"/storage/products/000000000000085.png\\\"]\"',0,'50072010',2.50,2.50,5.00,'2026-09-09 10:47:34','2026-09-09 12:39:47'),(31,'Virasat Silk Weaves | Handwoven Bhagalpuri Matka Silk Saree with Zari Pallu','<p><strong>Handwoven Bhagalpuri Matka Silk Saree</strong><span><span>&nbsp;</span>is handcrafted in the renowned Silk City of Bhagalpur. Spun from hand-reeled Matka silk yarns, it possesses a rustic tweed-like slub texture paired with an understated matte sheen. Finished with brushed antique gold zari stripes along the pallu and border, it offers effortless elegance from morning pooja to evening celebrations.</span></p>','ITM-BGL-015',18,1,1,'\"[\\\"Handcrafted in the Silk City of Bhagalpur from premium Matka silk yarns\\\",\\\"Rustic textured body with subtle natural sheen and graceful fall\\\",\\\"Antique brushed gold zari stripes along the pallu and borders\\\",\\\"Comfortable, wrinkle-resistant drape suited for extended festive wear\\\",\\\"Includes running matching Bhagalpuri silk blouse piece\\\"]\"','\"[{\\\"key\\\":\\\"Fabric\\\",\\\"value\\\":\\\"Pure Bhagalpuri Matka Raw Silk\\\"},{\\\"key\\\":\\\"Weave Type\\\",\\\"value\\\":\\\"Handloom Slub Weave\\\"},{\\\"key\\\":\\\"Length\\\",\\\"value\\\":\\\"5.5 Meters Saree + 0.8 Meter Blouse\\\"},{\\\"key\\\":\\\"Occasion\\\",\\\"value\\\":\\\"Festivals, Family Functions & Dinner Parties\\\"},{\\\"key\\\":\\\"Care Instructions\\\",\\\"value\\\":\\\"Dry Clean Only\\\"}]\"','/storage/products/000000000000086.png','\"[\\\"/storage/products/000000000000086.png\\\",\\\"/storage/products/000000000000087.png\\\",\\\"/storage/products/000000000000088.png\\\",\\\"/storage/products/000000000000089.png\\\",\\\"/storage/products/000000000000090.png\\\",\\\"/storage/products/000000000000091.png\\\",\\\"/storage/products/000000000000092.png\\\",\\\"/storage/products/000000000000093.png\\\",\\\"/storage/products/000000000000094.png\\\"]\"',0,'50072010',2.50,2.50,5.00,'2026-09-09 10:47:34','2026-09-09 12:40:20');
