DROP TABLE IF EXISTS `return_request_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `return_request_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `return_request_id` bigint unsigned NOT NULL,
  `order_item_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL,
  `variant_id` bigint unsigned NOT NULL,
  `quantity` int NOT NULL,
  `price` decimal(10,2) NOT NULL,
  `exchange_variant_id` bigint unsigned DEFAULT NULL,
  `qc_status` enum('pending','passed','failed') NOT NULL DEFAULT 'pending',
  `qc_remarks` text,
  `created_at` timestamp NOT NULL DEFAULT (now()),
  `updated_at` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `return_request_items_return_request_id_return_requests_id_fk` (`return_request_id`),
  KEY `return_request_items_order_item_id_order_items_id_fk` (`order_item_id`),
  KEY `return_request_items_product_id_products_id_fk` (`product_id`),
  KEY `return_request_items_variant_id_variants_id_fk` (`variant_id`),
  KEY `return_request_items_exchange_variant_id_variants_id_fk` (`exchange_variant_id`),
  CONSTRAINT `return_request_items_exchange_variant_id_variants_id_fk` FOREIGN KEY (`exchange_variant_id`) REFERENCES `variants` (`id`) ON DELETE SET NULL,
  CONSTRAINT `return_request_items_order_item_id_order_items_id_fk` FOREIGN KEY (`order_item_id`) REFERENCES `order_items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `return_request_items_product_id_products_id_fk` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `return_request_items_return_request_id_return_requests_id_fk` FOREIGN KEY (`return_request_id`) REFERENCES `return_requests` (`id`) ON DELETE CASCADE,
  CONSTRAINT `return_request_items_variant_id_variants_id_fk` FOREIGN KEY (`variant_id`) REFERENCES `variants` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

